            logging.error("Stopping on first failure: %s", sorted(failed))
            return 1

        running = (set(JOB_NAMES) - unscheduled) - (completed | failed)
        if not running and unscheduled:
            blocked = sorted(unscheduled)
            logging.error(
                "No runnable jobs left. Blocked jobs=%s (likely unmet deps due to failures)",
                blocked,
            )
            return 2

        if len(completed | failed) == len(JOB_NAMES):
            break

        resource_version = watch_for_job_updates(
            batch_api=batch_api,
            namespace=args.namespace,
            tracked_jobs=set(JOB_NAMES) - unscheduled,
            completed=completed,
            failed=failed,
            resource_version=resource_version,
            watch_timeout_seconds=args.watch_timeout_seconds,
        )

    if failed:
        logging.error(
            "Scheduling completed with failures. succeeded=%s failed=%s",
            sorted(completed),
            sorted(failed),
        )
        return 1

    logging.info("All jobs finished successfully: %s", sorted(completed))
    return 0

def schedule_ready_jobs(
    api_client: client.ApiClient,
    batch_api: client.BatchV1Api,
    namespace: str,
    manifest_paths: Dict[str, Path],
    output_dir: Path | None,
    dependencies: Dict[str, List[str]],
    unscheduled: set[str],
    completed: set[str],
    failed: set[str],
) -> List[str]:
    ready = [
        job for job in JOB_NAMES if job in unscheduled and all(prereq in completed for prereq in dependencies[job])
    ]

    for job in ready:
        try:
            yaml_objects = create_yaml_object(manifest_paths[job])
            yaml_objects = edit_job_configuration(yaml_objects)
            _write_effective_job_yaml_objects(
                output_dir=output_dir,
                job_name=job,
                yaml_objects=yaml_objects,
            )
            create_from_yaml(
                api_client,
                yaml_objects,
                namespace=namespace,
                verbose=False,
            )
            unscheduled.remove(job)
            logging.info("SCHEDULED job=%s deps=%s", job, dependencies[job])
        except (ApiException, FailToCreateError) as e:
            if e.status == 409:
                logging.warning("Job %s/%s already exists; tracking existing object", namespace, job)
                continue
            raise

    return ready

def create_yaml_object(manifest_path: str) -> List[Dict[str, Any]]:
    try:
        with open(os.path.abspath(manifest_path)) as f:
            yml_document_all = load_all(f, Loader=SafeLoader)
            return list(yml_document_all)
    except FileNotFoundError:
        raise FileNotFoundError("non existing configuration file")
    except Exception as e:
        raise Exception(f"Failed to load {manifest_path}: {e}")

def create_from_yaml(
    api_client: client.ApiClient,
    yaml_objects: List[Dict[str, Any]],
    namespace: str,
    verbose: bool = False,
) -> None:
    try:
        create_from_yaml(api_client, yaml_objects, namespace=namespace, verbose=verbose)
    except FailToCreateError as exc:
        if not isinstance(exc, list):
            raise  # If it's not a list, it's a single exception
        for e in exc:
            if e.status == 409:
                logging.warning("Job %s/%s already exists; tracking existing object", namespace, e.name)
            else:
                raise  # Re-raise other exceptions

def watch_for_job_updates(
    batch_api: client.BatchV1Api,
    namespace: str,
    tracked_jobs: set[str],
    completed: set[str],
    failed: set[str],
    resource_version: str,
    watch_timeout_seconds: int,
) -> str:
    watcher = watch.Watch()
    try:
        for event in watcher.stream(
            batch_api.list_namespaced_job,
            namespace=namespace,
            resource_version=resource_version,
            timeout_seconds=watch_timeout_seconds,
        ):
            obj = event["object"]
            if not obj or not obj.metadata or obj.metadata.name not in tracked_jobs:
                continue

            job_name = obj.metadata.name
            if job_name in completed or job_name in failed:
                continue

            state = parse_job_status(obj.status)
            if state == "succeeded":
                completed.add(job_name)
                logging.info("FINISHED job=%s status=Succeeded", job_name)
                if len(completed) == len(JOB_NAMES):
                    break
            elif state == "failed":
                failed.add(job_name)
                logging.info("FINISHED job=%s status=Failed", job_name)
                if len(failed) == len(JOB_NAMES):
                    break
            else:
                # Check if job is in running state and track progress
                if obj.status.conditions and obj.status.conditions[-1].type == "Running":
                    logging.info("JOB RUNNING: %s", job_name)
            if len(completed) == len(JOB_NAMES):
                break

            if obj.metadata and obj.metadata.resource_version:
                resource_version = obj.metadata.resource_version

        if len(completed) == len(JOB_NAMES):
            break
    finally:
        watcher.stop()

    return resource_version

def parse_job_status(status: client.V1JobStatus | None) -> str | None:
    if status is None:
        return None

    for condition in status.conditions or []:
        if condition.type == "Complete" and condition.status == "True":
            return "succeeded"
        if condition.type == "Failed" and condition.status == "True":
            return "failed"

    if status.succeeded and status.succeeded > 0:
        return "succeeded"
    if status.failed and status.failed > 0 and status.active in (None, 0):
        return "failed"
    return None

